/*
 * Hand-written MCP Events helpers. Not generated by Speakeasy: this file is not
 * tracked in .speakeasy/gen.lock, so it survives SDK regeneration.
 */

/**
 * JSON-RPC error codes for the MCP Events error kinds.
 *
 * Outpost fills `code` itself in every `mcp_error` it returns (its
 * `MCP_ERROR_CODES` setting). These codes only cover the errors the helpers
 * raise locally (a missing principal, a topic outside the allowlist, malformed
 * params), so pick the profile that matches the Outpost setting.
 */
export type McpEventsErrorCodes = {
  invalidParams: number;
  notFound: number;
  forbidden: number;
  resourceExhausted: number;
  unsupported: number;
  callbackEndpointError: number;
  internalError: number;
};

/**
 * `sketch` is the MCP Events design sketch numbering that ChatGPT follows (the
 * Outpost default). `sep-3415` is the provisional SEP-3415 numbering.
 */
export const MCP_EVENTS_ERROR_CODES = {
  sketch: {
    invalidParams: -32602,
    notFound: -32011,
    forbidden: -32012,
    resourceExhausted: -32013,
    unsupported: -32014,
    callbackEndpointError: -32015,
    internalError: -32603,
  },
  "sep-3415": {
    invalidParams: -32602,
    notFound: -32023,
    forbidden: -32024,
    resourceExhausted: -32025,
    unsupported: -32026,
    callbackEndpointError: -32027,
    internalError: -32603,
  },
} as const satisfies Record<string, McpEventsErrorCodes>;

export type McpEventsCodeProfile = keyof typeof MCP_EVENTS_ERROR_CODES;

export function resolveErrorCodes(
  codes: McpEventsCodeProfile | McpEventsErrorCodes | undefined,
): McpEventsErrorCodes {
  if (codes === undefined) {
    return MCP_EVENTS_ERROR_CODES.sketch;
  }
  if (typeof codes === "string") {
    const profile = MCP_EVENTS_ERROR_CODES[codes];
    if (!profile) {
      throw new TypeError(`Unknown MCP Events error code profile: ${codes}`);
    }
    return profile;
  }
  return codes;
}

/** The `mcp_error` object of an Outpost 422 response. */
export type McpErrorObject = {
  kind: string;
  code: number;
  message: string;
  data?: unknown;
};

/**
 * Outpost rejected an MCP call with an `mcp_error` (HTTP 422). `code`,
 * `message` and `data` are ready to send as the JSON-RPC error, so a JSON-RPC
 * layer that serializes thrown errors by duck typing (as the MCP SDKs do) can
 * let it propagate as is.
 */
export class MCPError extends Error {
  readonly statusCode: number;
  readonly mcpError: McpErrorObject;
  readonly kind: string;
  readonly code: number;
  readonly data: unknown;

  constructor(mcpError: McpErrorObject, statusCode = 422) {
    super(mcpError.message);
    this.name = "MCPError";
    this.statusCode = statusCode;
    this.mcpError = mcpError;
    this.kind = mcpError.kind;
    this.code = mcpError.code;
    this.data = mcpError.data;
  }
}

/**
 * Any other failure of an MCP endpoint call: a non-422 status, a network error,
 * a timeout or a malformed response. `body` holds at most the first KiB of the
 * response body, for logs. Never forward it to MCP clients.
 */
export class McpEventsRequestError extends Error {
  readonly statusCode: number | undefined;
  readonly body: string | undefined;

  constructor(
    message: string,
    options: { statusCode?: number; body?: string; cause?: unknown } = {},
  ) {
    super(message, options.cause === undefined ? undefined : { cause: options.cause });
    this.name = "McpEventsRequestError";
    this.statusCode = options.statusCode;
    this.body = options.body;
  }
}

/**
 * A JSON-RPC error raised by the MCP Events handlers. The MCP SDKs serialize
 * thrown errors by reading `code`, `message` and `data`, so this needs no
 * import of the host SDK's own error class.
 */
export class JSONRPCError extends Error {
  readonly code: number;
  readonly data: unknown;

  constructor(code: number, message: string, data?: unknown) {
    super(message);
    this.name = "JSONRPCError";
    this.code = code;
    this.data = data;
  }
}

// Bounds the body parsed out of a duck-typed error; real mcp_error bodies are
// a few hundred bytes.
const MAX_ERROR_BODY_CHARS = 64 * 1024;

/**
 * Returns the `mcp_error` carried by an error, by duck typing: this module's
 * MCPError, an error exposing `mcpError` (generated SDK error classes) or
 * `mcp_error`, or an Outpost HTTP error with status 422 and a JSON `body`
 * string. Returns undefined for anything else, including malformed objects.
 */
export function mcpErrorFrom(err: unknown): McpErrorObject | undefined {
  if (err instanceof MCPError) {
    return err.mcpError;
  }
  if (typeof err !== "object" || err === null) {
    return undefined;
  }
  const e = err as Record<string, unknown>;
  const direct = asMcpErrorObject(e["mcpError"]) ?? asMcpErrorObject(e["mcp_error"]);
  if (direct) {
    return direct;
  }
  const body = e["body"];
  if (
    e["statusCode"] === 422
    && typeof body === "string"
    && body.length <= MAX_ERROR_BODY_CHARS
  ) {
    try {
      const parsed: unknown = JSON.parse(body);
      if (isPlainObject(parsed)) {
        return asMcpErrorObject(parsed["mcp_error"]);
      }
    } catch {
      return undefined;
    }
  }
  return undefined;
}

/** Validates an mcp_error object; returns undefined unless it is well formed. */
export function asMcpErrorObject(value: unknown): McpErrorObject | undefined {
  if (!isPlainObject(value)) {
    return undefined;
  }
  const { kind, code, message, data } = value;
  if (
    typeof code !== "number"
    || !Number.isSafeInteger(code)
    || typeof message !== "string"
  ) {
    return undefined;
  }
  const out: McpErrorObject = {
    kind: typeof kind === "string" ? kind : "",
    code,
    message,
  };
  if (data !== undefined) {
    out.data = data;
  }
  return out;
}

export function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}
